use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k,
        k < list.len(),
    ensures
        // length decreases by exactly 1
        new_list.len() == list.len() - 1,

        // elements before the removed position are unchanged
        forall|i: int|
            0 <= i < (k as int - 1) ==> new_list[i] == list[i],

        // elements after the removed position shift left by 1
        forall|i: int|
            (k as int - 1) <= i < new_list.len() as int ==> new_list[i] == list[i + 1],

        // (optional derived property) every element of new_list comes from list
        forall|i: int|
            0 <= i < new_list.len() as int ==>
                exists|j: int| 0 <= j < list.len() as int && new_list[i] == list[j],
{
    // Preconditions (per problem statement): list is non-empty and 1 <= k < list.len()
    let n = list.len();
    assert!(n > 0, "list must be non-empty");
    assert!(k >= 1 && k < n, "k must satisfy 1 <= k < list.len()");

    let remove_idx = k - 1; // convert 1-based k to 0-based index

    let mut new_list = Vec::with_capacity(n - 1);
    new_list.extend_from_slice(&list[..remove_idx]);        // elements before k
    new_list.extend_from_slice(&list[remove_idx + 1..]);    // elements after k

    new_list
}

} // verus!

